class UserManagement {
    constructor() {
        this.users = []; // Stores user objects
    }

    /**
     * Adds a new user to the system.
     * @param {string} username - The username of the new user.
     * @param {object} userData - Additional data for the user.
     */
    addUser(username, userData) {
        // Assume userData is always valid for simplicity in this snippet
        this.users.push({ username: username, data: userData });
        console.log(`User ${username} added.`);
    }

    /**
     * Finds a user by their username.
     * @param {string} username - The username to search for.
     * @returns {object|null} The user object if found, otherwise null.
     */
    findUser(username) {
        for (let i = 0; i < this.users.length; i++) {
            if (this.users[i].username === username) {
                return this.users[i];
            }
        }
        return null;
    }
}
